// NOTE: Spawns a single max depth vox, generated by vox_type, with lod meshes for instancing
entity spawn_model_lods_generated(
    ecs* world,
    entity parent,
    const char* name,
    byte vox_type,
    color fill,
    byte max_depth,
    lint seed)
{
    entity e = spawn_vox_lods(
        world,
        parent,
        name,
        max_depth,
        NULL);
    zox_setv(e, Seed, seed);
    zox_setv(e, Color, fill);
    if (vox_type) {
        zox_setv(e, VoxType, vox_type);
        zox_setv(e, GenerateModel, zox_generate_model_run);
    }
    return e;
}
